do $ctrl$
declare
  v_total integer;
begin
  select count(*) into v_total from public.prompts where catalog_version = 'v2.1';
  if v_total < 200 then
    raise exception 'Lot 6 incomplet : % raccourcis importes au lieu de 200.', v_total;
  end if;
end $ctrl$;

